/* Inflate tests: every vector in inflate-vectors/ (generated by
 * gen-inflate-vectors.py with the system zlib) against its original in
 * brotli-vectors/, with whole, byte-at-a-time and random chunking;
 * truncation, corruption, trailing data and hand-made bad streams.
 *
 * usage: test_inflate ORIGINALS_DIR VECTOR... */
#include "brotli_util.h"
#include "codec/codec.h"

#include <time.h>

static int failures;

#define CHECK(cond, ...)                                                                                          \
    do {                                                                                                          \
        if (!(cond)) {                                                                                            \
            failures++;                                                                                           \
            printf("FAIL %s:%d: ", __FILE__, __LINE__);                                                           \
            printf(__VA_ARGS__);                                                                                  \
            printf("\n");                                                                                         \
        }                                                                                                         \
    } while (0)

/* Decodes with chunk sizes from rng (or fixed sizes when ichunk/ochunk are
 * nonzero). Returns the status; output in *out (malloc'd). */
static AuCodecStatus run(AuInflateFormat fmt, const uint8_t *in, size_t in_len, size_t ichunk, size_t ochunk,
                         BrRng *rng, uint8_t **out, size_t *out_len, size_t *left, size_t max_out)
{
    AuInflate *z = au_inflate_new(fmt);
    size_t cap = 1024, len = 0, pos = 0;
    uint8_t *buf = malloc(cap);
    AuCodecStatus st = AU_CODEC_OK;
    int stalls = 0;
    for (;;) {
        size_t ic = ichunk ? ichunk : br_rng_chunk(rng, 1 << 16);
        size_t oc = ochunk ? ochunk : br_rng_chunk(rng, 1 << 16);
        if (ic > in_len - pos)
            ic = in_len - pos;
        if (len + oc > cap) {
            while (len + oc > cap)
                cap *= 2;
            buf = realloc(buf, cap);
        }
        const uint8_t *ip = in + pos;
        size_t il = ic;
        uint8_t *op = buf + len;
        size_t ol = oc;
        st = au_inflate_run(z, &ip, &il, &op, &ol);
        size_t used = ic - il, made = oc - ol;
        pos += used;
        len += made;
        if (st != AU_CODEC_OK)
            break;
        if (len > max_out)
            break;
        if (!used && !made) {
            if (pos == in_len && ol)
                break; /* truncated: no input left */
            if (++stalls > 4)
                break;
        } else {
            stalls = 0;
        }
    }
    if (left)
        *left = in_len - pos;
    au_inflate_free(z);
    *out = buf;
    *out_len = len;
    return st;
}

static AuInflateFormat format_of(const char *path)
{
    const char *dot = strrchr(path, '.');
    if (dot && !strcmp(dot, ".gz"))
        return AU_INFLATE_GZIP;
    if (dot && !strcmp(dot, ".raw"))
        return AU_INFLATE_RAW;
    return AU_INFLATE_ZLIB;
}

static uint8_t *original_for(const char *dir, const char *vec, size_t *len)
{
    const char *base = strrchr(vec, '/');
    base = base ? base + 1 : vec;
    char name[256], path[1024];
    size_t n = strcspn(base, ".");
    if (n >= sizeof name)
        return NULL;
    memcpy(name, base, n);
    name[n] = 0;
    if (!strcmp(name, "multi")) {
        /* multi's original sits beside the vectors */
        snprintf(path, sizeof path, "%.*s%s", (int)(base - vec), vec, name);
        return br_read_file(path, len);
    }
    for (char *p = name; *p; p++)
        if (*p == '_')
            *p = '.';
    snprintf(path, sizeof path, "%s/%s", dir, name);
    return br_read_file(path, len);
}

static void test_vector(const char *dir, const char *path)
{
    size_t vlen, olen;
    uint8_t *v = br_read_file(path, &vlen);
    uint8_t *orig = original_for(dir, path, &olen);
    if (!v || !orig) {
        CHECK(0, "cannot read %s or its original", path);
        free(v);
        free(orig);
        return;
    }
    AuInflateFormat fmt = format_of(path);
    bool multi = strstr(path, "multi") != NULL;
    BrRng rng = {(uint32_t)vlen * 2654435761u + 1};
    uint8_t *out;
    size_t out_len, left;
    struct {
        size_t ic, oc;
    } modes[] = {{1 << 20, 1 << 20}, {1, 1 << 20}, {1 << 20, 1}, {1, 1}, {0, 0}, {0, 0}, {7, 3}};
    for (size_t m = 0; m < sizeof modes / sizeof modes[0]; m++) {
        AuCodecStatus st = run(fmt, v, vlen, modes[m].ic, modes[m].oc, &rng, &out, &out_len, &left, olen + 1);
        if (multi && st == AU_CODEC_DONE && left) {
            /* DONE at a member boundary when input arrives in pieces:
             * the driver above stops there; finish from that point. */
            st = AU_CODEC_OK;
        }
        if (!multi || modes[m].ic >= vlen) {
            CHECK(st == AU_CODEC_DONE, "%s mode %zu: status %d", path, m, st);
            CHECK(out_len == olen && !memcmp(out, orig, olen), "%s mode %zu: output differs (%zu vs %zu)", path,
                  m, out_len, olen);
        }
        free(out);
    }
    /* HTTP deflate accepts zlib and raw. */
    if (fmt != AU_INFLATE_GZIP) {
        AuCodecStatus st = run(AU_INFLATE_HTTP_DEFLATE, v, vlen, 0, 0, &rng, &out, &out_len, &left, olen + 1);
        CHECK(st == AU_CODEC_DONE && out_len == olen && !memcmp(out, orig, olen), "%s as HTTP deflate", path);
        free(out);
    }
    /* au_inflate_all, and its output cap. */
    {
        uint8_t *o;
        size_t ol;
        bool ok = au_inflate_all(fmt, v, vlen, olen ? olen : 1, &o, &ol);
        CHECK(ok && ol == olen && !memcmp(o, orig, olen), "%s inflate_all", path);
        au_free(o);
        if (olen > 1) {
            ok = au_inflate_all(fmt, v, vlen, olen - 1, &o, &ol);
            CHECK(!ok && !o, "%s inflate_all over the cap must fail", path);
        }
    }
    /* Trailing bytes stay in the input. */
    if (!multi) {
        uint8_t *t = malloc(vlen + 3);
        memcpy(t, v, vlen);
        memcpy(t + vlen, "XYZ", 3);
        AuCodecStatus st = run(fmt, t, vlen + 3, vlen + 3, 1 << 20, &rng, &out, &out_len, &left, olen + 1);
        CHECK(st == AU_CODEC_DONE && left == 3, "%s trailing bytes: status %d left %zu", path, st, left);
        free(out);
        free(t);
    }
    /* Every prefix (sampled for long vectors) is never DONE, never a crash. */
    if (!multi) {
        size_t step = vlen > 4000 ? vlen / 997 : 1;
        for (size_t n = 0; n < vlen; n += step) {
            AuCodecStatus st = run(fmt, v, n, 0, 0, &rng, &out, &out_len, &left, olen + 1);
            CHECK(st != AU_CODEC_DONE, "%s prefix %zu decoded as complete", path, n);
            CHECK(out_len <= olen && !memcmp(out, orig, out_len), "%s prefix %zu: wrong output", path, n);
            free(out);
        }
    }
    /* Corruption: no crash (ASan checks the rest); the output never
     * exceeds the bound. */
    for (int k = 0; k < 200 && vlen; k++) {
        uint8_t *c = malloc(vlen);
        memcpy(c, v, vlen);
        int flips = 1 + (int)(br_rng_next(&rng) % 4);
        for (int f = 0; f < flips; f++)
            c[br_rng_next(&rng) % vlen] ^= (uint8_t)(1u << (br_rng_next(&rng) % 8));
        run(fmt, c, vlen, 0, 0, &rng, &out, &out_len, &left, olen + 65536);
        free(out);
        free(c);
    }
    free(v);
    free(orig);
}

static AuCodecStatus run_bytes(AuInflateFormat fmt, const char *bytes, size_t n, const char **err)
{
    uint8_t outbuf[70000];
    AuInflate *z = au_inflate_new(fmt);
    const uint8_t *ip = (const uint8_t *)bytes;
    size_t il = n;
    uint8_t *op = outbuf;
    size_t ol = sizeof outbuf;
    AuCodecStatus st = au_inflate_run(z, &ip, &il, &op, &ol);
    static char msg[128];
    snprintf(msg, sizeof msg, "%s", au_inflate_error(z));
    *err = msg;
    au_inflate_free(z);
    return st;
}

static void test_bad_streams(void)
{
    const char *err;
    /* Raw: block type 3. */
    CHECK(run_bytes(AU_INFLATE_RAW, "\x07", 1, &err) == AU_CODEC_ERROR, "block type 3");
    /* Stored block with LEN/NLEN mismatch. */
    CHECK(run_bytes(AU_INFLATE_RAW, "\x01\x05\x00\xfa\xfe", 5, &err) == AU_CODEC_ERROR, "stored nlen: %s", err);
    /* Stored block OK: "hello". */
    CHECK(run_bytes(AU_INFLATE_RAW, "\x01\x05\x00\xfa\xffhello", 10, &err) == AU_CODEC_DONE, "stored ok: %s", err);
    /* Fixed block: a match at distance 1 with no history. Literal-free:
     * length code 257 (0000001, 7 bits), distance code 0 (00000). */
    {
        /* bits LSB first: BFINAL=1, BTYPE=01, then 0000001 reversed... build
         * with a tiny bit writer. */
        uint8_t b[8] = {0};
        int pos = 0;
#define PUT(v, n)                                                                                                 \
    for (int i_ = 0; i_ < (n); i_++, pos++)                                                                       \
        if (((v) >> i_) & 1)                                                                                      \
            b[pos >> 3] |= (uint8_t)(1 << (pos & 7));
#define PUTREV(code, n)                                                                                           \
    for (int i_ = (n)-1; i_ >= 0; i_--, pos++)                                                                    \
        if (((code) >> i_) & 1)                                                                                   \
            b[pos >> 3] |= (uint8_t)(1 << (pos & 7));
        PUT(1, 1);
        PUT(1, 2);
        PUTREV(1, 7); /* symbol 257 */
        PUTREV(0, 5); /* distance 1 */
        PUTREV(0, 7); /* end of block */
        CHECK(run_bytes(AU_INFLATE_RAW, (const char *)b, 4, &err) == AU_CODEC_ERROR, "distance too far: %s", err);
        /* Fixed: distance code 30 is invalid. */
        memset(b, 0, sizeof b);
        pos = 0;
        PUT(1, 1);
        PUT(1, 2);
        PUTREV(0x30 + 'a', 8); /* literal 'a' */
        PUTREV(1, 7);
        PUTREV(30, 5);
        CHECK(run_bytes(AU_INFLATE_RAW, (const char *)b, 5, &err) == AU_CODEC_ERROR, "distance code 30: %s", err);
        /* Fixed: length symbol 286 is invalid (11000110, 8 bits). */
        memset(b, 0, sizeof b);
        pos = 0;
        PUT(1, 1);
        PUT(1, 2);
        PUTREV(0x30 + 'a', 8);
        PUTREV(0xC6, 8);
        PUTREV(0, 5);
        CHECK(run_bytes(AU_INFLATE_RAW, (const char *)b, 5, &err) == AU_CODEC_ERROR, "length code 286: %s", err);
    }
    /* Dynamic block with HLIT 30 (287 codes) is refused: BFINAL 1, BTYPE 10,
     * HLIT 30, HDIST 0, HCLEN 0. */
    {
        uint8_t b[4] = {0};
        int pos = 0;
        PUT(1, 1);
        PUT(2, 2);
        PUT(30, 5);
        PUT(0, 5);
        PUT(0, 4);
        CHECK(run_bytes(AU_INFLATE_RAW, (const char *)b, 3, &err) == AU_CODEC_ERROR, "HLIT 287: %s", err);
        /* Code length code with all zero lengths, then a symbol: empty
         * code, every symbol is invalid. */
        memset(b, 0, sizeof b);
        pos = 0;
        PUT(1, 1);
        PUT(2, 2);
        PUT(0, 5);
        PUT(0, 5);
        PUT(0, 4);
        for (int i = 0; i < 4; i++)
            PUT(0, 3);
        CHECK(run_bytes(AU_INFLATE_RAW, (const char *)b, 4, &err) == AU_CODEC_ERROR, "empty CL code: %s", err);
    }
    /* zlib: bad check, preset dictionary, bad Adler. */
    CHECK(run_bytes(AU_INFLATE_ZLIB, "\x78\x9d\x03\x00", 4, &err) == AU_CODEC_ERROR, "zlib FCHECK");
    CHECK(run_bytes(AU_INFLATE_ZLIB, "\x78\xbb\x00\x00\x00\x01\x03\x00", 8, &err) == AU_CODEC_ERROR, "zlib FDICT");
    CHECK(run_bytes(AU_INFLATE_ZLIB, "\x78\x9c\x03\x00\x00\x00\x00\x02", 8, &err) == AU_CODEC_ERROR, "zlib adler");
    CHECK(run_bytes(AU_INFLATE_ZLIB, "\x78\x9c\x03\x00\x00\x00\x00\x01", 8, &err) == AU_CODEC_DONE, "zlib empty: %s",
          err);
    /* gzip: reserved flags, wrong CRC, wrong size, wrong magic. */
    CHECK(run_bytes(AU_INFLATE_GZIP, "\x1f\x8b\x08\x20\0\0\0\0\0\x03\x03\0\0\0\0\0\0\0\0\0", 20, &err) ==
              AU_CODEC_ERROR,
          "gzip reserved flag");
    CHECK(run_bytes(AU_INFLATE_GZIP, "\x1f\x8b\x08\x00\0\0\0\0\0\x03\x03\0\x01\0\0\0\0\0\0\0", 20, &err) ==
              AU_CODEC_ERROR,
          "gzip crc");
    CHECK(run_bytes(AU_INFLATE_GZIP, "\x1f\x8b\x08\x00\0\0\0\0\0\x03\x03\0\0\0\0\0\x01\0\0\0", 20, &err) ==
              AU_CODEC_ERROR,
          "gzip size");
    CHECK(run_bytes(AU_INFLATE_GZIP, "\x1f\x8b\x08\x00\0\0\0\0\0\x03\x03\0\0\0\0\0\0\0\0\0", 20, &err) ==
              AU_CODEC_DONE,
          "gzip empty: %s", err);
    CHECK(run_bytes(AU_INFLATE_GZIP, "\x1f\x8c", 2, &err) == AU_CODEC_ERROR, "gzip magic");
    /* Errors are sticky. */
    {
        AuInflate *z = au_inflate_new(AU_INFLATE_RAW);
        const uint8_t *ip = (const uint8_t *)"\x07\x01";
        size_t il = 2;
        uint8_t o[4], *op = o;
        size_t ol = 4;
        CHECK(au_inflate_run(z, &ip, &il, &op, &ol) == AU_CODEC_ERROR, "sticky 1");
        ip = (const uint8_t *)"\x03\x00";
        il = 2;
        CHECK(au_inflate_run(z, &ip, &il, &op, &ol) == AU_CODEC_ERROR, "sticky 2");
        au_inflate_free(z);
    }
    /* Checksums against known values. */
    CHECK(au_codec_crc32(0, "123456789", 9) == 0xCBF43926u, "crc32 check value");
    CHECK(au_codec_adler32(1, "Wikipedia", 9) == 0x11E60398u, "adler32 check value");
}

/* Throughput on the largest vector, decoded repeatedly. */
static void bench(const char *path, const char *dir)
{
    size_t vlen, olen;
    uint8_t *v = br_read_file(path, &vlen);
    uint8_t *orig = original_for(dir, path, &olen);
    if (!v || !orig)
        return;
    uint8_t *out = malloc(olen + 1);
    clock_t t0 = clock();
    int reps = 0;
    while (clock() - t0 < CLOCKS_PER_SEC / 5) {
        AuInflate *z = au_inflate_new(format_of(path));
        const uint8_t *ip = v;
        size_t il = vlen;
        uint8_t *op = out;
        size_t ol = olen + 1;
        au_inflate_run(z, &ip, &il, &op, &ol);
        au_inflate_free(z);
        reps++;
    }
    double s = (double)(clock() - t0) / CLOCKS_PER_SEC;
    printf("inflate %s: %.1f MB/s of output\n", path, (double)olen * reps / s / 1e6);
    free(out);
    free(v);
    free(orig);
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: test_inflate ORIGINALS_DIR VECTOR...\n");
        return 2;
    }
    for (int i = 2; i < argc; i++)
        test_vector(argv[1], argv[i]);
    test_bad_streams();
    for (int i = 2; i < argc; i++)
        if (strstr(argv[i], "page_html.6.z"))
            bench(argv[i], argv[1]);
    printf("%d vectors, %d failures\n", argc - 2, failures);
    return failures ? 1 : 0;
}
